// lifenote/config — wholesale regen (mako-style key=value). Palette roles,
// border styles, opacity and anchor come from the theme; the rest (font, TTF
// path, timeouts, sizes) are reproduced at their current values — per-consumer
// font sizes are not driven by [font].size in M1 (see plan Risk #8).

use crate::theme::{hash, Theme};

pub fn render(t: &Theme) -> String {
    let p = &t.palette;
    let n = &t.lifenote;
    format!(
        "# lifenote — box-drawing-framed notifications. Generated by lifeconf.\n\
         # Edit ~/.config/lifeconf/theme.toml (or run `lifeconf`), not this file.\n\n\
         border-style={border_style}\n\
         critical-border-style={crit_style}\n\n\
         font=/usr/share/fonts/TTF/ShureTechMonoNerdFontMono-Regular.ttf\n\
         font-px=15\n\n\
         background-color={surface}\n\
         background-alpha={alpha}\n\
         text-color={text}\n\
         border-color={border}\n\
         title-color={accent}\n\
         warn-color={warn}\n\
         urgent-color={urgent}\n\n\
         default-timeout={timeout_ms}\n\
         critical-timeout=0\n\n\
         max-width=40\n\
         max-visible={max_visible}\n\
         max-lines=6\n\n\
         anchor={anchor}\n\
         margin=8\n\
         layer=top\n\n\
         dismiss-on-click-outside={click_out}\n\
         mute-apps={muted}\n",
        border_style = n.border_style,
        crit_style = n.critical_border_style,
        surface = hash(&p.surface),
        alpha = n.opacity,
        text = hash(&p.text),
        border = hash(&p.border),
        accent = hash(&p.accent),
        warn = hash(&p.warn),
        urgent = hash(&p.urgent),
        anchor = n.position,
        click_out = n.dismiss_on_click_outside,
        timeout_ms = n.timeout_seconds as u64 * 1000,
        max_visible = n.max_visible.clamp(1, 20),
        // One line, commas only: a newline would start a new config key.
        muted = n.muted_apps.replace(['\n', '\r', '='], " "),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn timeout_count_and_muted_apps_are_emitted() {
        let mut t = Theme::default();
        let r = render(&t);
        assert!(r.contains("default-timeout=3000") && r.contains("max-visible=5") && r.contains("mute-apps=\n"));
        t.lifenote.timeout_seconds = 0;
        t.lifenote.muted_apps = "vesktop, element\nlayer=overlay".into();
        let r = render(&t);
        assert!(r.contains("default-timeout=0\n"));
        assert!(r.contains("mute-apps=vesktop, element layer overlay\n"), "no key injection: {r}");
    }

    #[test]
    fn click_outside_is_emitted() {
        let mut t = Theme::default();
        assert!(render(&t).contains("dismiss-on-click-outside=false"));
        t.lifenote.dismiss_on_click_outside = true;
        assert!(render(&t).contains("dismiss-on-click-outside=true"));
    }
}
